-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (ENAMED 2025, enamed-2025): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 133 correções de texto em 62 questões (85 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'enamed-2025';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"enamed_2025_q003","code":"ENAMED-2025-Q003","campos":{"statement":{"antes_md5":"7827759572f487cae65b3bc64d0a95bb","depois":"Homem de 45 anos foi encontrado inconsciente por familiares junto a uma escada de sua casa. Familiares o conduziram em carro próprio, sem medidas-padrão de atendimento pré-hospitalar. Não sabem por quanto tempo ficou desacordado e nem sobre o histórico de saúde. Quando deu entrada no pronto-socorro, encontrava-se inconsciente, com equimose e escoriações na região orbital e palpebral direita, além de escoriações na região cervical posterior e em membros à direita. Não apresentava resposta ao comando verbal, mas respirava espontaneamente com frequência normal. Pressão arterial de 140 x 90 mmHg e pupilas isocóricas. Durante a avaliação, abriu os olhos e começou a se mexer, ainda sem responder a questões ou comandos. Após 30 minutos começou a responder, mas informava não se lembrar de ter caído da escada. Considerando o quadro, a conduta adequada é"}}},{"id":"enamed_2025_q006","code":"ENAMED-2025-Q006","campos":{"statement":{"antes_md5":"70a3dd8c4429096e5baa32dc714caf7a","depois":"Observe o encaminhamento realizado por um médico de família. “À cardiologia, Encaminho o Sr. J. L. S., de 56 anos, com diagnóstico de cardiopatia isquêmica, que sofreu um infarto agudo do miocárdio há 3 meses. Tem orientação para o uso de antiagregantes plaquetários, mas tem história de úlcera péptica e teve reação alérgica ao clopidogrel e à ticlopidina. Desta forma, solicito orientação quanto à conduta preventiva.” Ao ser assistido pelo cardiologista, o paciente será atendido em qual nível de atenção e receberá que tipo de prevenção, respectivamente?"}}},{"id":"enamed_2025_q007","code":"ENAMED-2025-Q007","campos":{"statement":{"antes_md5":"6c4e8752ed35fb45e9252afc7d3ce2cd","depois":"Homem de 20 anos, com diagnóstico de esquizofrenia, chega à Unidade de Pronto Atendimento (UPA) acompanhado de familiares, que descrevem que o paciente acordou “torto”. Há 5 dias, foi realizada a troca de risperidona por haloperidol, pois aquela estava em falta na farmácia. Paciente nega outras queixas clínicas. Ao exame, apresenta contratura de região cervical e fácies de dor. Quais são, respectivamente, a hipótese diagnóstica mais provável e a conduta mais adequada?"}}},{"id":"enamed_2025_q009","code":"ENAMED-2025-Q009","campos":{"statement":{"antes_md5":"0ad241fea317ad35890db94f8dfb2fdf","depois":"Paciente de 7 anos, na 4ª semana de tratamento quimioterápico para leucemia linfocítica aguda, é admitido em hospital terciário com história de febre há 12 horas (temperatura axilar de 39 ºC), tosse e dispneia. Após 24 horas da admissão, segue febril, apesar de ter usado dipirona há 1 hora, e mantém diurese de 2 mL/kg/h. Exame físico: hidratado; pálido; orientado no tempo e no espaço; frequência cardíaca de 130 bpm; temperatura axilar de 39 ºC; frequência respiratória de 36 irpm; pressão arterial de 90 x 60 mmHg; boa perfusão periférica; murmúrio vesicular diminuído em base de hemitórax à direita, com crepitações; bulhas taquicárdicas; fígado a 4 cm do rebordo costal direito e 5 cm do apêndice xifoide; baço a 4 cm do rebordo costal esquerdo. Os exames laboratoriais evidenciam lactato aumentado, acidose metabólica e hemograma com leucocitose com desvio à esquerda. Com base no quadro descrito, o diagnóstico é"}}},{"id":"enamed_2025_q010","code":"ENAMED-2025-Q010","campos":{"statement":{"antes_md5":"197b838b0ae8b29130f3384827013d59","depois":"Paciente feminina de 78 anos, com 24 horas de evolução de dor e abaulamento progressivo em região inguinal direita. Apresentou também alguns episódios de vômitos e diminuição da eliminação de flatos. Antecedentes: neoplasia de mama há 30 anos, diabetes mellitus há 20 anos e tabagista de 40 maços/ano. Ao exame estava normotensa, eucárdica, afebril, eupneica. Índice de massa corporal de 35 kg/m². Abdome globoso, depressível, com abaulamento não redutível e desconforto à palpação em região inguinal direita, com discreta hiperemia local e sem sinais de irritação peritoneal. Resultados dos exames laboratoriais: Exame Resultado Valor de referência Hemoglobina 13 g/dL 11 a 15 g/dL Leucócitos 10.300/mL 4.000 a 11.000/mL Plaquetas 261.000/mm3 150 a 300.000/mm3 Creatinina 1,8 mg/dL 0,7 a 1,3 mg/dL Ureia 65 mg/dL 40 a 80 mg/dL A hipótese diagnóstica mais provável é","sem_tabela_md5":"e8c72369f575f8d6e67a68b6f0b417a1"},"A":{"antes_md5":"d41d8cd98f00b204e9800998ecf8427e","depois":"isquemia mesentérica."},"B":{"antes_md5":"d41d8cd98f00b204e9800998ecf8427e","depois":"hérnia inguinal indireta."}}},{"id":"enamed_2025_q011","code":"ENAMED-2025-Q011","campos":{"statement":{"antes_md5":"9ba9179c9e60b7ac2d546afb4daae945","depois":"Paciente de 25 anos, com duas gestações e um parto, no segundo trimestre de gestação, compareceu à primeira consulta de pré-natal sem queixas. Após orientações e realização dos testes rápidos, verificou-se que o teste para sífilis foi positivo e imediatamente a paciente recebeu 2,4 milhões UI de penicilina benzatina intramuscular. Paciente nega diagnóstico e tratamento prévios para sífilis. Em relação ao acompanhamento da paciente, é correto afirmar que"}}},{"id":"enamed_2025_q012","code":"ENAMED-2025-Q012","campos":{"statement":{"antes_md5":"576809715de271a1d30c0fe186a8b24d","depois":"Homem de 52 anos, branco, solteiro, comparece à consulta agendada na Unidade Básica de Saúde (UBS) desejando realizar revisão clínica e exames laboratoriais. Desde os 35 anos não faz acompanhamento de saúde. Relata história familiar de diabetes e hipertensão, e a mãe faleceu com câncer de pulmão. Sem história familiar de câncer de próstata. Fuma cerca de 2 maços por dia há 21 anos. Exame físico: pressão arterial de 120 x 80 mmHg, índice de massa corporal de 23 kg/m², sem outras alterações. Considerando as recomendações de rastreamento para esse paciente, o médico de família e comunidade deve"},"D":{"antes_md5":"41d982906ca75660c5d09335aedadcee","depois":"solicitar exames de colesterol total, HDL e triglicerídeos, glicemia de jejum, pesquisa de sangue oculto nas fezes, ofertar testes rápidos para HIV, sífilis e hepatites B e C; realizar abordagem sobre possibilidade de cessação do tabagismo."}}},{"id":"enamed_2025_q015","code":"ENAMED-2025-Q015","campos":{"statement":{"antes_md5":"f405ca5d2a2e875292f9d5f02dd320b4","depois":"Homem de 50 anos, queixando-se de astenia e constipação com fezes em fita. Há 15 dias, apresenta edema de membros inferiores até a raiz da região crural, bilateralmente, com pouca melhora à elevação dos membros. Ele perdeu 10 kg em 6 meses. Nega hipertensão arterial e diabetes mellitus e não faz uso de medicamento. Os exames do paciente apresentaram os seguintes resultados: Exame Resultado Valor de referência Pressão arterial 130 x 80 mmHg -- Peso 70 kg - Hematócrito 35% 48 a 69% Glicemia 88 mg/dL 60 a 100 mg/dL Albumina sérica 1,8 g/dL 3,8 a 4,8 g/dL Creatinina 1,2 mg/dL 0,7 a 1,3 mg/dL Triglicerídeos 200 mg/dL < 150 mg/dL Proteína urinária 3,6 g/24 horas < 100 mg/24 horas de 24 horas proteínas +++ Sedimentos hemácias + (5 por campo) Dentre esses achados laboratoriais, quais são necessários para a definição da síndrome renal do paciente?","sem_tabela_md5":"bb3b390cc9a44cf33522aac4a0d0a9de"}}},{"id":"enamed_2025_q016","code":"ENAMED-2025-Q016","campos":{"D":{"antes_md5":"78d64383ce52374ab92574f9eadd8b07","depois":"curvas de crescimento da OMS até os dois anos e, a partir daí, em curvas específicas para síndrome de Down."}}},{"id":"enamed_2025_q017","code":"ENAMED-2025-Q017","campos":{"statement":{"antes_md5":"94b2dd515ca5d8964bfafb1f1cd1d1b9","depois":"Paciente de 20 anos, sexo masculino, vítima de colisão “automóvel a muro”, sem cinto de segurança, é atendido ainda na cena pelo Serviço Móvel de Atendimento de Urgência (SAMU). Exame físico: paciente torporoso; saturação de O₂ de 60%, em ar ambiente; frequência respiratória de 28 irpm; frequência cardíaca de 112 bpm; pressão arterial de 90 x 50 mmHg. Desvio da traqueia para a direita, turgência de veias jugulares, hipofonese de bulhas cardíacas e diminuição acentuada do murmúrio vesicular à esquerda. Qual é a conduta adequada no atendimento pré-hospitalar?"},"C":{"antes_md5":"b03a2d3b0686d4589e61da6492600b08","depois":"Pericardiocentese."}}},{"id":"enamed_2025_q019","code":"ENAMED-2025-Q019","campos":{"statement":{"antes_md5":"ec244253e55ad9ad54cfbdd36b6c5340","depois":"Mulher de 82 anos, sem história prévia de hipertensão, comparece à consulta preocupada porque aferiu a pressão na farmácia há 1 semana e estava em 146 x 86 mmHg. Em outra aferição, há 2 semanas, na unidade de saúde, a pressão estava em 144 x 88 mmHg. No momento da consulta, a pressão está em 148 x 88 mmHg. Não apresenta sintomas nem está em acompanhamento de outros agravos neste momento. Qual é a abordagem adequada nesse caso?"}}},{"id":"enamed_2025_q020","code":"ENAMED-2025-Q020","campos":{"statement":{"antes_md5":"953305d18a61ef5a3c0821b4a6e5dda4","depois":"Mulher travesti de 28 anos, profissional do sexo, comparece à Unidade Básica de Saúde (UBS) em demanda espontânea. Relata relações sexuais frequentes com diferentes parceiros, com uso inconsistente de preservativos, principalmente durante relações anais receptivas. Há 2 dias teve uma relação sexual desprotegida com um cliente que se recusou a usar camisinha. Nunca utilizou medicamento para profilaxia pré-exposição (PrEP) ou pós-exposição (PEP) à infecção pelo HIV. Considerando que a paciente está assintomática no momento, qual a melhor estratégia de prevenção?"}}},{"id":"enamed_2025_q021","code":"ENAMED-2025-Q021","campos":{"statement":{"antes_md5":"048942162cf027d3ed5fbf2489e7610e","depois":"Mulher de 21 anos comparece à consulta médica em Unidade Básica de Saúde (UBS) para avaliação de amenorreia há 4 meses, sendo descartada gravidez. Paciente relata que há 10 meses iniciou dieta para perder peso, tendo emagrecido nesse período aproximadamente 30 kg. Há 2 dias relata desmaio durante prática de exercício físico e, por isso, realizou eletrocardiograma (ECG) que indicou alterações no segmento ST e na onda T. Paciente nega histórico de diagnóstico de transtorno mental, mora sozinha e sua família é de outra cidade. Afirma manter o padrão alimentar, pois ainda quer perder peso. Ao exame físico, apresenta palidez de mucosa e turgor cutâneo diminuído. Altura = 1,63 m; peso = 39 kg (IMC = 14,7 kg/m²); pressão arterial = 80 x 60 mmHg; frequência cardíaca = 55 bpm e frequência respiratória = 15 irpm. Qual é a conduta adequada nesse momento?"}}},{"id":"enamed_2025_q022","code":"ENAMED-2025-Q022","campos":{"statement":{"antes_md5":"bed414c6096d7b965a8c4704a778ee93","depois":"Mulher de 65 anos iniciou quadro de lentidão dos movimentos há 6 meses, com dificuldade para amarrar sapatos, abotoar roupas e digitar. Ao caminhar, apresentava passos mais curtos e sensação de instabilidade, com 1 episódio de queda. Concomitantemente apresentou tremores nas mãos, de repouso, associados à rigidez e alteração do padrão do sono. Nega alterações de memória e cognição. Ao exame físico apresentava fácies em máscara, marcha em pequenos passos, frequência cardíaca de 88 bpm com ausculta sem alterações, pressão arterial de 130 x 80 mmHg, tremores assimétricos na manobra dos braços estendidos, hipertonia em roda dentada. A ressonância nuclear magnética realizada há 2 semanas constatou atrofia cerebral compatível com a idade. O tratamento medicamentoso inicial recomendado para o caso clínico será"}}},{"id":"enamed_2025_q023","code":"ENAMED-2025-Q023","campos":{"A":{"antes_md5":"2f95546bbe7dc705b3f1f29028bd0329","depois":"Manuel, 15 anos, abandonado pelos pais e sob os cuidados de uma família acolhedora, apresenta febre, vômitos, petéquias que evoluem para púrpuras em MMII e SS, rigidez de nuca e história vacinal desconhecida."},"C":{"antes_md5":"15e6b00b5b8110326d34f506fd5dc74f","depois":"Felipe, 11 anos, acolhido em um abrigo desde os 9 anos, há 3 dias está mais recolhido no seu quarto e dorme quase o tempo todo. Apresenta febre, muita dor no corpo e retro-orbitária, sangramento gengival quando escova os dentes e petéquias pelo corpo."},"D":{"antes_md5":"ef7874c81299ad7004e23c6e31cf7b66","depois":"Edilene, 16 anos, que cumpre medidas socioeducativas em uma instituição do Estado, apresenta várias equimoses nos membros superiores e inferiores, além do tronco. Refere também suores noturnos, febre inexplicada, perda de peso e linfonodos aumentados de tamanho em região cervical, supraclavicular e inguinal bilateralmente."}}},{"id":"enamed_2025_q024","code":"ENAMED-2025-Q024","campos":{"statement":{"antes_md5":"981a044e7b4c229dcf330f699a1918d5","depois":"Paciente do sexo feminino, 27 anos, é atendida em Unidade de Pronto Atendimento (UPA) com história de dor abdominal, com início em epigástrio há dois dias, contínua, sem fatores de melhora, associada a náuseas e perda de apetite, evoluindo para dor em fossa ilíaca direita há 1 dia e febre de 38,2 ºC no dia do atendimento. Nega comorbidades, cirurgias prévias ou uso de medicações regulares. Relata que a última menstruação foi há 23 dias, e apresenta ciclos regulares de 28 dias. Exame físico: regular estado geral, corada, desidratada +/4+, eupneica, anictérica, acianótica; ausculta pulmonar e cardíaca sem alterações; ruídos hidroaéreos diminuídos, descompressão brusca dolorosa em quadrante inferior de abdome à direita. Exame Resultado Valor de referência Hemoglobina 10,7 g/dL 11,5 a 15,5 g/dL Hematócrito 37% 38 a 52% Leucócitos 13.400/mm3 4.000 a 11.000/mm3 totais Bastonetes 7% 0 a 5% Urina 25 leucócitos/campo Hemácias 8 hemácias/campo Beta-hCG negativo sérico Considerando o diagnóstico mais provável, a conduta adequada é","sem_tabela_md5":"c135d12c2637d93a731c32f5e6dd9515"}}},{"id":"enamed_2025_q026","code":"ENAMED-2025-Q026","campos":{"statement":{"antes_md5":"8c3508619bd373583f3080dde5bf252d","depois":"Homem de 34 anos se dirige à Unidade Básica de Saúde (UBS) com febre (38,5 ºC), dores de moderada intensidade e manchas no corpo há 3 dias. No dia da consulta, iniciou com dores abdominais e vômitos incontroláveis. Exame físico: prostrado, mucosas coradas, extremidades bem perfundidas. Pressão arterial de 120 x 80 mmHg; frequência respiratória de 16 irpm; frequência cardíaca de 80 bpm. Leve dor à palpação abdominal, sem outras alterações. Qual a hipótese diagnóstica e o manejo, respectivamente?"}}},{"id":"enamed_2025_q028","code":"ENAMED-2025-Q028","campos":{"statement":{"antes_md5":"324dd195868373a43b2f86608b0e9488","depois":"“Internações sem consentimento aumentam na Cracolândia, em meio a denúncias de agressões”. ZYLBERKAN, M.; KRUSE, T. Folha de S. Paulo, 3 jul. 2024. Notícias como esta têm se tornado frequentes em jornais brasileiros nos últimos anos. Alguns municípios têm criado leis locais próprias para as internações involuntárias que muitas vezes contradizem as leis federais sobre o tema. Sobre a internação involuntária no Brasil, é correto afirmar que"}}},{"id":"enamed_2025_q031","code":"ENAMED-2025-Q031","campos":{"statement":{"antes_md5":"0a3033e6e12172dfe162fe70b7eb59a5","depois":"Mulher de 72 anos foi atendida em hospital de médio porte. Relatava emagrecimento e dor abdominal com irradiação para região dorsal há 3 meses; há 1 mês a urina ficou mais escura, começou a apresentar prurido cutâneo intenso e icterícia em escleras. Ao exame físico, encontrava-se ictérica +++/4+, emagrecida; exame do abdome com fígado palpável abaixo da borda costal direita, assim como uma massa bem definida, de consistência cística, não dolorosa em hipocôndrio direito. Nesse caso, o mais adequado é solicitar"}}},{"id":"enamed_2025_q032","code":"ENAMED-2025-Q032","campos":{"statement":{"antes_md5":"7b4bfe9be36e14229b8c9e8cdcd93bde","depois":"Paciente G5P3C1, 35 anos, idade gestacional de 15 semanas por ecografia relizada com 8 semanas, hipertensa crônica em uso de enalapril, antecedente de pré-eclâmpsia. Comparece à consulta de pré-natal na Unidade Básica de Saúde (UBS) com pressão arterial de 140 x 90 mmHg. Qual é a conduta medicamentosa indicada para essa paciente?"}}},{"id":"enamed_2025_q033","code":"ENAMED-2025-Q033","campos":{"C":{"antes_md5":"62fc672be8ffb975eabb846d17700763","depois":"Se o TRM-TB for negativo e a baciloscopia for positiva, solicitar cultura de escarro com teste de sensibilidade e reiniciar o esquema básico enquanto se aguarda a cultura."}}},{"id":"enamed_2025_q035","code":"ENAMED-2025-Q035","campos":{"statement":{"antes_md5":"4b5a2cfd878866da1dc5d8e566fe130b","depois":"Mulher de 52 anos chega ao acolhimento de Unidade Básica de Saúde (UBS), muito chorosa, e relata: “Estou com dificuldade para dormir, não tenho comido direito, desde o ocorrido ... é o meu filho, sabe ... ele morreu há 3 dias ... e a dor no meu coração está muito forte, quase insuportável”. A paciente chora copiosamente e diz que sonha com uma pessoa gritando o nome de seu filho, relembrando o momento em que o tinha encontrado na rua, vítima de atropelamento. Após o primeiro acolhimento, ela fica um pouco mais calma, relatando que não pensa em se matar, que nunca tinha sido atendida por psiquiatra ou tomado medicamentos antes, mas que nesse momento precisa de muita ajuda. Diante do caso, qual a conduta adequada?"},"A":{"antes_md5":"352575c745add90aefb227d9b7af784d","depois":"Prescrever inibidor de recaptação de serotonina para alívio dos sintomas depressivos e ansiosos."}}},{"id":"enamed_2025_q037","code":"ENAMED-2025-Q037","campos":{"statement":{"antes_md5":"f454cb83e2f209fff3b937af77341cee","depois":"Menino, 10 anos, morador de área urbana, está em avaliação no pronto-atendimento por apresentar dor em cotovelo direito há 1 dia. Há 1 semana, iniciou quadro de febre de 38,5 ºC, 1 a 2 picos ao dia, associada à dificuldade de deambular devido ao joelho direito apresentar-se “doloroso e inchado”. Após 4 dias, percebeu melhora da dor no joelho, porém o tornozelo direito começou a ficar “inchado e um pouco avermelhado”, doloroso, com melhora em 2 dias. Há 3 semanas, havia se queixado de dor de garganta. Sem outras queixas. Nega contato com animais domésticos. No momento do atendimento, está com dificuldade para movimentar o cotovelo direito por causa da dor e do edema, frequência cardíaca de 110 bpm e 2 bulhas rítmicas normofonéticas, com sopro sistólico de 3+/6+. Restante do exame físico sem anormalidades. Considerando o quadro clínico apresentado, o agente etiológico e o tratamento de escolha são, respectivamente,"}}},{"id":"enamed_2025_q038","code":"ENAMED-2025-Q038","campos":{"statement":{"antes_md5":"1ce957abc09b9efd7dce10c79c484c13","depois":"Homem de 58 anos deu entrada no pronto-socorro com dor epigástrica irradiada para as costas, iniciada há 2 horas, progressiva, pós-prandial, acompanhada de náuseas, vômitos e sudorese. Relata episódios semelhantes no último ano, que melhoraram com uso de analgésico. Tabagista ativo, alcoolista de 8 doses de destilado por dia há 33 anos, nega comorbidades. Exame físico: corado, acianótico, anictérico, sudoreico, fácies de dor, agitado. Índice de massa corporal de 23 kg/m²; pressão arterial de 150 x 90 mmHg; frequência cardíaca de 74 bpm; frequência respiratória de 18 irpm; temperatura axilar de 37 ºC. Abdome globoso, distendido, timpânico, peristalse presente, doloroso à palpação do epigástrio e hipocôndrio esquerdo. Os exames laboratoriais apresentam os seguintes resultados: Exame Resultado Valor de referência Hematócrito 46% 36 a 46% Hemoglobina 15,0 g/dL 12,0 a 15,0 g/dL Leucócitos 12.000/mm3 4.000 a 10.000/mm3 Glicose 120 mg/dL 70 a 99 mg/dL Bilirrubina total 1,2 mg/dL 0,3 a 1,3 mg/dL Ureia 38 mg/dL 15 a 40 mg/dL Cálcio 8,9 mg/dL 8,7 a 10,2 mg/dL Amilase 35 U/L 20 a 96 U/L Lipase 12 U/L 3 a 43 U/L Fosfatase alcalina 81 U/L 33 a 96 U/L LDH 127 U/L 100 a 190 U/L TGO 36 U/L 5 a 40 U/L Qual é o provável diagnóstico?","sem_tabela_md5":"54a77cb42c0c23b87ac0fdec9523d4b5"}}},{"id":"enamed_2025_q039","code":"ENAMED-2025-Q039","campos":{"B":{"antes_md5":"397d325823b2059188c9b13aa69b8cfa","depois":"solicitar dopplervelocimetria obstétrica para avaliar o bem-estar fetal e planejar o manejo com base no resultado."},"C":{"antes_md5":"19c4e20c284c953394093a1358d82481","depois":"realizar amnioscopia para verificar a presença de mecônio no líquido amniótico e planejar o manejo com base no resultado."},"D":{"antes_md5":"98ea849b3207763738180a5786c0404c","depois":"solicitar perfil biofísico fetal e cardiotocografia a cada 2 a 3 dias e planejamento da indução do parto até 41 semanas e 6 dias."}}},{"id":"enamed_2025_q041","code":"ENAMED-2025-Q041","campos":{"statement":{"antes_md5":"1ba9c3e07aacb7b8ad120fa30fc89818","depois":"Homem de 21 anos, portador de diabetes mellitus tipo 1, diagnosticado há 5 anos, foi levado à Unidade de Pronto Atendimento (UPA) devido à dor abdominal, náuseas e vômitos. Familiares informam que está sem utilizar insulina há 3 dias por dificuldades financeiras. No exame físico, encontra-se torporoso, desidratado, com hálito cetótico e dor abdominal à palpação profunda de forma generalizada. Ao exame, frequência cardíaca de 112 bpm; frequência respiratória de 38 irpm; pressão arterial de 110 x 70 mmHg. Os exames laboratoriais na admissão indicam: Exame Resultado Valor de referência Glicemia 472 mg/dL 60 a 100 mg/dL Gasometria arterial pH de 7,2 7,35 a 7,45 Bicarbonato 10 mEq/L 22 a 26 mEg/L Creatinina 1,6 mg/dL 0,7 a 1,3 mg/dL Potássio sérico 3,0 mEq/L 3,5 a 5,5 mEq/L O diagnóstico e a conduta inicial indicada para esse paciente são, respectivamente,","sem_tabela_md5":"6e41333bc6422a869e4631bb466d1f36"}}},{"id":"enamed_2025_q042","code":"ENAMED-2025-Q042","campos":{"statement":{"antes_md5":"9c6f498b8679a0aa6c9c0bda36244a14","depois":"Recém-nascido de 14 dias, hipoativo e com desconforto respiratório, é levado para avaliação na Unidade de Pronto Atendimento (UPA). Antecedentes obstétricos: não foi realizado pré-natal e o parto ocorreu a termo no domicílio. Exame clínico: hipoativo e pouco responsivo, hipocorado, cianótico. Aparelho respiratório: 70 irpm com tiragem subcostal. Murmúrio vesicular diminuído bilateralmente. Saturação de O₂ em ar ambiente de 82%. Aparelho cardiovascular: pulsos débeis, tempo de perfusão capilar de 5 segundos. Frequência cardíaca de 160 bpm, com ritmo cardíaco regular. Abdome globoso, com fígado a 2,5 cm do rebordo costal direito, presença de halo de hiperemia e edema em torno do coto umbilical. O diagnóstico e as condutas adequadas são, respectivamente,"}}},{"id":"enamed_2025_q043","code":"ENAMED-2025-Q043","campos":{"statement":{"antes_md5":"736a1feef0c977ee42e7ecf30d01d7de","depois":"Homem de 66 anos, em pós-operatório precoce de revascularização cardíaca, é encaminhado ao pronto-socorro, com queixa de dor abdominal progressiva em quadrante inferior esquerdo há 5 dias e piora há 1 dia, com aumento do número de evacuações para 3 vezes ao dia. Relata febre não aferida. Exame físico: bom estado geral, eupneico, pressão arterial de 110 x 60 mmHg, temperatura axilar de 38 ºC e frequência cardíaca de 100 bpm. Ao exame abdominal, defesa voluntária da musculatura e dor à palpação superficial e profunda, com massa em quadrante inferior esquerdo. Ao toque retal, presença de uma massa flutuante dolorosa à esquerda. Tomografia de abdome com contraste: densificação dos planos gordurosos adjacente ao sigmoide, associada a coleção de 100 mm³ no local. Após iniciada a antibioticoterapia sistêmica, qual é a conduta mais adequada para esse paciente?"}}},{"id":"enamed_2025_q045","code":"ENAMED-2025-Q045","campos":{"C":{"antes_md5":"634c5b8994c7e8fe4cb8d2a736897866","depois":"solicitar internação social, a fim de garantir tratamento supervisionado, observado diretamente por 6 meses, caso seja confirmada a tuberculose."},"D":{"antes_md5":"b9a7158ff12dfca444077083ab6a8892","depois":"aguardar evolução, com uso de sintomáticos; caso a tosse persista por mais de 3 semanas, proceder à investigação diagnóstica de tuberculose."}}},{"id":"enamed_2025_q046","code":"ENAMED-2025-Q046","campos":{"statement":{"antes_md5":"0c5c985ae81e4d2ccb871248e189e0ed","depois":"Homem de 32 anos apresenta quadro de dor lombar crônica de início insidioso, com duração aproximada de 6 meses, que piora pela manhã e melhora com o movimento. Refere rigidez matinal, principalmente nas regiões lombar e sacroilíaca, com duração de mais de 30 minutos, com dor nas articulações sacroilíacas e sensação de fadiga durante as últimas semanas. Não há histórico de trauma. A história familiar é positiva para doenças reumatológicas, mas o paciente desconhece diagnósticos específicos. O painel de autoanticorpos apresenta: Positivo Anticorpo antinuclear (ANA) Título 1:80 Padrão homogêneo/difuso Anticorpo anti-DNA dupla hélice Negativo Antígeno leucocitário Positivo humano B27 (HLA-B27) Fator reumatoide Negativo Anticorpo anti-CCP Negativo Anticorpo anti-Ro Negativo Anticorpo anti-La Negativo Com base no caso clínico e nos exames laboratoriais apresentados, qual é o diagnóstico mais provável?","sem_tabela_md5":"5649074581b3f2f32c54921305b2684c"}}},{"id":"enamed_2025_q048","code":"ENAMED-2025-Q048","campos":{"A":{"antes_md5":"f5ce4fd391175f1e8715d7f96b5504a0","depois":"Ressonância magnética; programação cirúrgica."}}},{"id":"enamed_2025_q049","code":"ENAMED-2025-Q049","campos":{"statement":{"antes_md5":"58f7a702a358213ae4d122672af35e0c","depois":"Nulípara de 30 anos, com diagnóstico de lúpus eritematoso sistêmico e história recente de trombose venosa, apresenta ciclos menstruais prolongados de 8 a 10 dias, com intenso sangramento e cólicas fortes, busca orientação sobre métodos contraceptivos. Considerando os critérios de elegibilidade para uso de anticoncepção e o quadro clínico, qual é a melhor opção de contracepção?"}}},{"id":"enamed_2025_q050","code":"ENAMED-2025-Q050","campos":{"statement":{"antes_md5":"c52239eef1c4d523882c82a28b77ae33","depois":"Homem de 55 anos, com diagnóstico de diabetes mellitus, foi em consulta de rotina em Unidade Básica de Saúde (UBS) levando exames laboratoriais solicitados pelo médico na consulta anterior. Faz uso de metformina 850 mg, 3 vezes ao dia, e glicazida 30 mg, 1 vez ao dia, há mais de 6 meses. Os exames laboratoriais atuais apresentam hemoglobina glicada de 9,5% e creatinina sérica de 0,8 mg/dL. Qual das condutas é a mais adequada para o seguimento desse caso?"},"A":{"antes_md5":"785e0b0779a530fa153713076725ddf6","depois":"Suspender os medicamentos orais, iniciar insulina NPH 10 UI subcutânea pela manhã e 20 UI à noite. Monitorar a glicemia pré-prandial, e, quando estiver controlada, medir a glicemia pós-prandial para avaliação da introdução da insulina regular."},"C":{"antes_md5":"a0238c2041d19dbdb8ee24284794dd50","depois":"Manter a dose de metformina e glicazida, iniciar insulina NPH 10 UI subcutânea à noite, associada à monitorização glicêmica de jejum. Ajustar 2 a 3 UI a cada 2 a 3 dias, até atingir a meta da glicemia de jejum."}}},{"id":"enamed_2025_q051","code":"ENAMED-2025-Q051","campos":{"statement":{"antes_md5":"c694d933e2b11faa606c4df70dea671c","depois":"Homem de 38 anos retorna a ambulatório de clínica médica de um hospital de atenção secundária, onde faz acompanhamento clínico de retocolite ulcerativa. Analisando os exames complementares solicitados na última consulta, o médico atendente observa elevações significativas da fosfatase alcalina e gama-GT, com discreta elevação dos níveis séricos de aminotransferases, sem hiperbilirrubinemia. Questionado, o paciente refere apenas leve desconforto no hipocôndrio direito. Ao exame físico, não há icterícia, febre ou presença de sinal de Murphy. Considerando a doença de base do caso, o exame complementar indicado e seu resultado provável são, respectivamente,"}}},{"id":"enamed_2025_q054","code":"ENAMED-2025-Q054","campos":{"statement":{"antes_md5":"c4af7971b1db35bdefef77d39f0f18ed","depois":"Uma adolescente de 15 anos comparece em consulta ginecológica com a finalidade de iniciar contracepção. Na história patológica pregressa, refere episódios de enxaqueca com aura. Nos antecedentes familiares, relata que a avó materna teve diagnóstico de câncer de mama, sua mãe é hipertensa e sua irmã tem diabetes. O uso do contraceptivo combinado está contraindicado para essa paciente devido ao risco de"}}},{"id":"enamed_2025_q055","code":"ENAMED-2025-Q055","campos":{"A":{"antes_md5":"ef2a3c58ed1ffc108acb7b7c59566f47","depois":"Pneumocócica 23-valente, 1 dose, com reforço em 5 anos; dupla adulto (dT – contra difteria e tétano), a cada 10 anos; contra influenza e covid-19, anualmente; contra hepatite B, 3 doses. Agendar uma nova visita domiciliar com mais membros da família para dialogar sobre a situação."},"B":{"antes_md5":"9162bd2bd50c128d3243011bf7525ac3","depois":"Contra influenza e covid-19, anualmente; dupla adulto (dT – contra difteria e tétano), a cada 10 anos; contra hepatite B, 3 doses; contra herpes-zoster, 2 doses. Fazer denúncia ao Conselho Municipal do Idoso sobre não vacinação do idoso."},"C":{"antes_md5":"d8d1ecea7488a57254cc97712c2cd041","depois":"Pneumocócica 10-valente, 1 dose, com reforço em 5 anos; dupla adulto (dT – contra difteria e tétano), a cada 10 anos; contra influenza e covid-19, anualmente; contra hepatite B, 3 doses. Solicitar que a filha assine um termo de responsabilidade em relação à não vacinação do pai."},"D":{"antes_md5":"b6cbf9e8ea65f25f9baf112fb3f55c1a","depois":"Pneumocócica 10-valente, 1 dose, com reforço em 5 anos; contra influenza e covid-19, anualmente; contra herpes-zoster, 2 doses; dupla adulto (dT – contra difteria e tétano), a cada 10 anos. Respeitar a autonomia da filha sobre a vacinação, uma vez que é a cuidadora responsável."}}},{"id":"enamed_2025_q056","code":"ENAMED-2025-Q056","campos":{"statement":{"antes_md5":"46ef4f4248026375045d1b581eea87d0","depois":"O vírus Chikungunya é transmitido pelo mosquito Aedes sp e foi responsável por grandes epidemias associadas a desfechos clínicos agudos, crônicos e graves. As ações voltadas para o controle do Aedes sp incluem medidas como o manejo integrado de vetores, que envolve atividades a serem executadas pela equipe de vigilância do território em um processo cíclico, tais como"},"C":{"antes_md5":"bce0d9de34c195e463b06a3a1b24a0cd","depois":"vigilância virológica, notificação semanal dos casos suspeitos de Chikungunya em áreas sem transmissão e definição do local provável de infecção."}}},{"id":"enamed_2025_q058","code":"ENAMED-2025-Q058","campos":{"statement":{"antes_md5":"d783de2a494e53c9c31cba321bec6bba","depois":"Mulher de 45 anos é internada em hospital de média complexidade com queixas de febre (em torno de 38 ºC), mialgia, mal-estar e dor na região cervical anterior, irradiada para a mandíbula e orelhas. Há 2 semanas, iniciou quadro sugestivo de infecção viral respiratória alta, com evolução clínica lenta desde então, passando a sentir palpitações e tremores nos últimos 3 dias. Procurou atendimento na unidade de saúde. Ao exame físico, a paciente se encontra febril, com taquicardia desproporcional à temperatura corporal e tremores finos nas extremidades. À palpação da tireoide: glândula dolorosa, firme e levemente aumentada de tamanho, assimétrica, não nodular. As dosagens da velocidade de hemossedimentação e proteína C reativa se mostraram elevadas. Considerando a principal hipótese diagnóstica para o caso, quais exames complementares a sustentariam e qual o tratamento indicado, respectivamente?"}}},{"id":"enamed_2025_q060","code":"ENAMED-2025-Q060","campos":{"statement":{"antes_md5":"0a9983b01249d1ff0108c9a170e82fd9","depois":"Paciente masculino, 59 anos, atendido em hospital terciário com queixa de dor de moderada intensidade em fossa ilíaca esquerda (FIE), com início há 5 dias. Apresentou temperatura de 38 ºC nas últimas 48 horas, associada à prostração. Não possuía comorbidades. Relatou episódio semelhante de menor intensidade há cerca de 1 ano, com resolução espontânea e um episódio de hematoquezia há 6 meses. No momento se encontra em regular estado geral, discretamente desidratado, com frequência cardíaca de 95 bpm; pressão arterial de 140 x 90 mmHg; índice de massa corporal de 30,5 mg/kg². Abdome flácido, doloroso à palpação profunda em FIE e hipogástrio, com plastrão palpável em hipogástrio. Hemograma: leucócitos de 17.000/mm³ (valor de referência: 5.000 a 10.000/mm³), 7% de bastões (valor de referência: 0 a 5%). Considerando o quadro, qual é o exame complementar de maior acurácia para estabelecer o diagnóstico?"}}},{"id":"enamed_2025_q062","code":"ENAMED-2025-Q062","campos":{"A":{"antes_md5":"997464f87ebb99d2724dd9c978d8a515","depois":"pelo Instituto Médico Legal e constar: Parte I: a) Insuficiência respiratória aguda grave (horas); b) Síndrome gripal (10 dias); c) Hipertensão arterial sistêmica (30 anos). Parte II: Acidente vascular encefálico (5 anos)."},"B":{"antes_md5":"83883b1f89c35cc90542741b505b79a1","depois":"pela médica e constar: Parte I: a) Insuficiência respiratória aguda grave (horas); b) Pneumonia (1 dia); Síndrome gripal (10 dias). Parte II: a) Acidente vascular encefálico (5 anos); b) Hipertensão arterial sistêmica (30 anos)."},"C":{"antes_md5":"19a19d9f12892897776d18f86b76dd39","depois":"pelo Serviço Móvel de Atendimento de Urgência (SAMU) e constar: Parte I: a) Síndrome gripal (10 dias); b) Pneumonia (1 dia); c) Insuficiência respiratória aguda grave (horas). Parte II: a) Acidente vascular encefálico (5 anos); b) Hipertensão arterial sistêmica (30 anos)."}}},{"id":"enamed_2025_q064","code":"ENAMED-2025-Q064","campos":{"statement":{"antes_md5":"7780b50b710550f3347d0c5c37744217","depois":"Homem de 23 anos, estudante universitário, é levado à Unidade de Pronto Atendimento (UPA) por um amigo da moradia estudantil, que o encontrou chorando, trancado no banheiro com diversas cartelas de medicamentos próximas de si. O paciente nega ter ingerido qualquer fármaco ou outras substâncias, mas admite estar pensando em dar fim à própria vida. Refere tristeza profunda há cerca de 2 meses, com piora recente após o término de um relacionamento. Diz estar “sem propósito na vida” e que “ninguém sentiria falta” se ele morresse. Conta que viu na internet que tomar muitos comprimidos de paracetamol seria a melhor forma de morrer. Relata insônia inicial e terminal, perda de apetite, queda de rendimento acadêmico e isolamento social. Nega uso atual de drogas ilícitas, mas admite consumo de álcool eventualmente. Abandonou psicoterapia após 2 sessões. Todos os familiares vivem em outro estado. Ao exame, apresenta-se vígil, orientado, com discurso discretamente lentificado, sem alucinações ou delírios evidentes. O contato visual é pobre, o afeto está intensamente rebaixado e não modulante. Exames laboratoriais gerais solicitados à chegada na UPA não mostram alterações. Qual é a conduta adequada ao caso clínico apresentado?"}}},{"id":"enamed_2025_q065","code":"ENAMED-2025-Q065","campos":{"D":{"antes_md5":"29b240f503c98a43ef0ff601413f2381","depois":"Níveis reduzidos de Fator de Von Willebrand."}}},{"id":"enamed_2025_q068","code":"ENAMED-2025-Q068","campos":{"statement":{"antes_md5":"951ec6993fe341597742bb44b98eca0f","depois":"Uma mulher de 30 anos recebeu a citologia oncótica com laudo de “atipias celulares escamosas de significado indeterminado, onde não se pode afastar alto grau (ASC-H)”. Ela nega antecedente de tabagismo e não se lembra de ter tido infecção sexualmente transmissível. Nesse caso, a conduta adequada deve ser a realização de"}}},{"id":"enamed_2025_q069","code":"ENAMED-2025-Q069","campos":{"C":{"antes_md5":"1295cce69b1e78fc1db861870aee463e","depois":"o tempo que é gasto para obter a substância ou recuperar-se de seus efeitos."}}},{"id":"enamed_2025_q070","code":"ENAMED-2025-Q070","campos":{"A":{"antes_md5":"a194b127aba544585e21ea06b6ac3d20","depois":"solicitar o isolamento imediato dos casos sintomáticos, iniciar tratamento individual conforme avaliação clínica, recomendar higienização de colchões e ampliar o fornecimento de sabão e escovas pessoais."},"B":{"antes_md5":"c7d0aa1cc3ec76eafa2cf6410d86bc76","depois":"implementar bloqueio coletivo com tratamento simultâneo, notificar o surto ao serviço de vigilância em saúde, reorganizar fluxos com a administração prisional e planejar medidas educativas e estruturais."}}},{"id":"enamed_2025_q072","code":"ENAMED-2025-Q072","campos":{"statement":{"antes_md5":"80fe93c58d18ae14610e8e7135ddbda6","depois":"Homem de 35 anos, índice de massa corporal de 15 kg/m², é internado devido à diarreia líquida, com produtos patológicos, acompanhada de flatulência e desconforto abdominal há 4 semanas. Apresentou emagrecimento de cerca de 10 kg em 1 mês. Foram solicitados exames com endoscopia digestiva alta e baixa, sem alterações macroscópicas. Estudos histopatológicos de estômago, intestino delgado e cólon normais. Teste respiratório com lactulose positivo. O plano terapêutico adequado para esse paciente será"},"A":{"antes_md5":"ff0bf5b2e4b06f356ef7ea792617584e","depois":"neomicina e rifaximina."}}},{"id":"enamed_2025_q073","code":"ENAMED-2025-Q073","campos":{"statement":{"antes_md5":"ddfff19fbcdf0de468c582d5edb7c72c","depois":"Criança de 2 anos encaminhada ao matriciamento de pediatria, com história de ter apresentado há 7 dias uma crise tônico-clônica generalizada em vigência de temperatura axilar de 39,3 ºC, duração de 2 minutos, sem recorrência em 24 horas. Naquela ocasião foi realizado exame físico e neurológico, compatível com infecção viral de vias aéreas superiores, sem outras alterações. A conduta adequada nesse caso é"}}},{"id":"enamed_2025_q075","code":"ENAMED-2025-Q075","campos":{"statement":{"antes_md5":"6d556a80a522fa37127f59b3f09b10ab","depois":"Paciente de 29 anos, nuligesta, ciclos menstruais com intervalos de 20 a 65 dias, duração de 4 a 10 dias, intensidade moderada. Apresenta índice de massa corporal de 41,5 kg/m² e se submeterá à cirurgia bariátrica em alguns meses. Necessita de orientação para contracepção. Com base nessas informações, assinale a alternativa correta."}}},{"id":"enamed_2025_q076","code":"ENAMED-2025-Q076","campos":{"A":{"antes_md5":"f65e1d97c5751f97eb4cfb51cd313f62","depois":"solicitar teste rápido para sífilis, HIV e hepatites B e C. Em caso de teste reagente para sífilis, prescrever penicilina G benzatina. Prescrever 1 comprimido de tenofovir/lamivudina (TDF/3TC) 300 mg/300 mg + 1 comprimido de dolutegravir (DTG) 50 mg ao dia, durante 28 dias."}}},{"id":"enamed_2025_q078","code":"ENAMED-2025-Q078","campos":{"C":{"antes_md5":"cba62ba54d9d98bbf483208cb127b4b1","depois":"Encaminhar paciente para serviço especializado e informar que o seguimento relacionado à transição de gênero deve ser feito com especialista."}}},{"id":"enamed_2025_q079","code":"ENAMED-2025-Q079","campos":{"statement":{"antes_md5":"5f8d08f7755a8f7e037db2d143addbcb","depois":"Mulher de 62 anos, com histórico de infecções do trato urinário de repetição, dá entrada em Unidade de Pronto Atendimento (UPA) com quadro de febre alta e calafrios. A paciente é portadora de diabetes mellitus tipo 2, em tratamento regular com metformina e glicazida. À admissão apresenta-se com pressão arterial de 110 x 70 mmHg, frequência cardíaca de 106 bpm, frequência respiratória de 25 irpm e temperatura axilar de 38 ºC. Os exames laboratoriais indicam hemoglobina de 12,3 g/dL e hematócrito de 36%; leucócitos de 14.000/mm³ (valor de referência: 6.000 a 10.000/mm³), com 84% de neutrófilos e 12% de bastonetes; plaquetas de 210.000/mm³. A conduta para o caso deve ser recomendar"}}},{"id":"enamed_2025_q080","code":"ENAMED-2025-Q080","campos":{"statement":{"antes_md5":"230f5d608a88af54603b7272818b6f8f","depois":"Recém-nascido a termo apresenta, no 1º minuto de vida, quadro de apneia e bradicardia, desvio do ictus à direita, abdome escavado e presença de ruídos hidroaéreos à ausculta do hemitórax esquerdo. No decorrer do atendimento desse recém-nascido, em sala de parto, os procedimentos adequados a serem realizados são"}}},{"id":"enamed_2025_q083","code":"ENAMED-2025-Q083","campos":{"statement":{"antes_md5":"ce395b7296e03dc69ac87b0d23f4bf38","depois":"Mulher de 32 anos, sexualmente ativa, comparece à consulta com o médico de família e comunidade para realização do seu primeiro exame preventivo. O médico realiza a coleta de citologia oncótica. Após 3 semanas, a paciente retorna com o resultado “presença de lesão intraepitelial de baixo grau”. Considerando esse resultado, qual é a conduta adequada do médico?"}}},{"id":"enamed_2025_q086","code":"ENAMED-2025-Q086","campos":{"statement":{"antes_md5":"554ba0972ba00c9ac1279d5cfac97328","depois":"Mulher de 55 anos, sem história de doenças crônicas, procura atendimento por queixa de cefaleia persistente em ambos os lados do crânio, associada a alterações de visão (amaurose fugaz e diplopia), cansaço e artralgias. Relata dor em todo o couro cabeludo. Notou perda de peso (2 kg em 2 meses). Nega fotofobia ou fonofobia, febre ou náuseas, e afirma que não acorda de madrugada por conta da cefaleia. Nega qualquer problema de ordem emocional. Ao exame, a paciente encontra-se afebril, com pupilas isocóricas e sem rigidez de nuca. Qual é o tipo de cefaleia dessa paciente, e qual exame seria útil na sua investigação preliminar, respectivamente?"}}},{"id":"enamed_2025_q088","code":"ENAMED-2025-Q088","campos":{"statement":{"antes_md5":"64f07721bcce6dfc70a4f2c14c2047c6","depois":"Homem de 72 anos, encaminhado a ambulatório especializado, com queixa de dor epigástrica, com irradiação em faixa para região dorsal há 3 meses e perda de 8 kg. Queixa-se que na última semana está com prurido, icterícia, náuseas, colúria e acolia. Refere carga tabágica de 30 maços/ano e consumo de bebida alcoólica há 35 anos. Há 15 anos, trata de dislipidemia, hipertensão arterial e diabetes mellitus. Índice de massa corporal de 30 kg/m². Com base na principal hipótese diagnóstica, quais exames iniciais devem ser solicitados?"},"A":{"antes_md5":"464624b915ca111e56d0ed9bdc1d2bf0","depois":"Ultrassonografia de abdome, dosagem de aminotransferases, bilirrubinas e sorologias para hepatites."},"D":{"antes_md5":"c8662ba8bed3e0127055fa405aaf5383","depois":"Tomografia de abdome com contraste e dosagem de CA 19.9."}}},{"id":"enamed_2025_q090","code":"ENAMED-2025-Q090","campos":{"A":{"antes_md5":"8515c891a8962540d7cb453b7f53f4ee","depois":"higienizar adequadamente e suturar as lacerações; aplicar o soro antirrábico; prescrever 1 dose de penicilina benzatina 1,2 milhão de UI."}}},{"id":"enamed_2025_q091","code":"ENAMED-2025-Q091","campos":{"statement":{"antes_md5":"a91efc0dadc92a4f42b44cb5ea69780c","depois":"Homem de 56 anos, em acompanhamento médico por angina instável de início recente, diabetes mellitus tipo 2, hipertensão arterial sistêmica e dislipidemia, é internado em unidade coronariana de hospital de atenção terciária com quadro de dor torácica em aperto, de forte intensidade, irradiada para o membro superior esquerdo e mandíbula, iniciada há cerca de 2 horas. O paciente relata ter sofrido 3 episódios de dor com características similares, mas de menor duração, nas últimas 24 horas. Ele vem em uso crônico de losartana, hidroclorotiazida, ácido acetilsalicílico, dapagliflozina, metformina e atorvastatina. Ao exame físico, ausculta-se 4ª bulha, níveis pressóricos dentro da normalidade, sem congestão pulmonar. Um eletrocardiograma mostra novo infradesnivelamento segmento ST de 1 mm, com inversão de onda T, em parede anterior. O paciente evolui com elevação da troponina-I, fazendo curva enzimática. O escore de risco Grace é de 152 pontos, enquanto o TIMI risk score é de 5 pontos. A conduta indicada nesse caso é realizar"}}},{"id":"enamed_2025_q093","code":"ENAMED-2025-Q093","campos":{"A":{"antes_md5":"2574193a200208b7acb1749c2812c736","depois":"Prescrição de analgésico tópico e colírio lubrificante."}}},{"id":"enamed_2025_q094","code":"ENAMED-2025-Q094","campos":{"statement":{"antes_md5":"395333ce43f97e1c5a7f2a0abd0a5762","depois":"Mulher de 72 anos, previamente hígida, com menopausa aos 53 anos, obesa, solteira e nulípara, nunca fez reposição hormonal. Chega à Unidade de Pronto Atendimento (UPA) com sangramento vaginal há dois dias, hemodinamicamente estável. Nega sangramentos anteriores. Realizou exame especular, com os seguintes achados: mucosa vaginal sem alterações, colo uterino contendo lesão polipoide que se exteriorizava pelo orifício externo, ectocérvice sem alterações, anexos livres. À ultrassonografia transvaginal, útero contendo 3 nódulos, medindo respectivamente 2,5 cm, 3,5 cm e 1,5 cm em seus maiores diâmetros, sendo o 1º e o 2º intramurais e o 3º submucoso. Endométrio medindo 8 mm de espessura. Colo uterino mostrando lesão polipoide no canal endocervical, medindo 1,5 cm em sua maior dimensão. Qual é a principal hipótese diagnóstica?"}}},{"id":"enamed_2025_q095","code":"ENAMED-2025-Q095","campos":{"statement":{"antes_md5":"2c34ba4fc9b03263d12bb31aa25a98a2","depois":"Menina de 11 anos é levada pela mãe à consulta médica em Unidade Básica de Saúde (UBS), com história de cansaço, palidez cutânea e baixo rendimento escolar nos últimos 3 meses. Ao exame físico, mucosas hipocrômicas (3+/4+); palidez cutânea. Pulso radial: 104 bpm, rítmico e cheio. Aparelho cardiovascular: sopro sistólico 2/6. Restante do exame físico sem alterações. Mãe apresenta hemograma da menina realizado há 2 semanas. Resultados Valores de referência Hemoglobina 8,4 g/dL 11,5 a 15,5 g/dL Hematócrito 25,3% 36 a 48% VCM 62 fL 80 a 98 fL HCM 24 pg 27 a 34 pg CHCM 28g/dL 31 a 36 g/dL RDW 22% 11,5 a 14,5% Leucócitos totais 8.430/mm3 4.000 a 10.000/mm3 Neutrófilos 54% 40 a 80% Eosinófilos 10% 0 a 5% Basófilos 1% 0 a 2% Monócitos 4% 2 a 10% Linfócitos 31% 25 a 50% Plaquetas 480.000/mm3 140.000 a 450.000/mm3 Diante do caso apresentado, assinale a alternativa mais adequada.","sem_tabela_md5":"eab9b76beff7e013c4d8dc6dfe97f34c"},"B":{"antes_md5":"4313217d49587e46ccb9004abf54662b","depois":"Considerando-se o resultado dos exames, pode-se iniciar tratamento com 4 mg/kg/dia de ferro elementar, e espera-se aumento de reticulócitos em 4 a 7 dias."}}},{"id":"enamed_2025_q097","code":"ENAMED-2025-Q097","campos":{"statement":{"antes_md5":"80b5ab8d2c89d6d807cec0dc9c35d34c","depois":"Mãe de menina de 7 anos, em consulta na Unidade Básica de Saúde (UBS), relata preocupação por a filha ser a menor de sua sala de aula. Nega intercorrências nos períodos gestacional e neonatal. Nega internações ou uso de medicações contínuas. Exame físico sem alterações, estágio de desenvolvimento de Tanner M1P1; peso de 19 kg (z-1); estatura de 1,07 m (-3 < z <-2) com alvo de 1,50 m (z-2); índice de massa corporal de 16,6 (0 < z < +1); relação entre segmento superior e segmento inferior de 1,02 (valor de referência para a idade: 1 a 1,3). Em consulta com 6 anos e 8 meses, apresentava peso de 17 kg (-2 < z <-1); estatura de 1,05 m (-3 < z <-2); índice de massa corporal de 15,4 (z 0), quando foi realizado cálculo de idade óssea compatível com 5 anos e 10 meses. A hipótese diagnóstica adequada para o caso é"}}},{"id":"enamed_2025_q098","code":"ENAMED-2025-Q098","campos":{"statement":{"antes_md5":"20bf9b808a6bd507e68c07372aa82a36","depois":"Paciente de 43 anos, sexo feminino, internada em enfermaria de cirurgia. Refere icterícia, colúria e acolia, iniciadas há 72 horas. Paciente nega tabagismo, comorbidades ou episódios semelhantes previamente. Exame físico: ictérica (+++/++++), dor à palpação profunda de hipocôndrio direito; frequência cardíaca de 83 bpm; pressão arterial de 123 x 76 mmHg; temperatura axilar de 37,4 ºC. Ultrassonografia de abdome: presença de múltiplas imagens móveis e arredondadas, de 0,5 a 1 cm de diâmetro, e dilatação de vias biliares intra e extra-hepáticas. Exames laboratoriais: Exame Resultado Valor de referência Hematócrito 50% 38 a 52% Leucócitos totais 9.000/mL 4.000 a 11.000/mL Bastões 3% 0 a 5% Creatinina 0,9 mg/dL 0,7 a 1,3 mg/dL TGO 45 U/L 4 a 35 U/L TGP 38 U/L 4 a 32 U/L Fosfatase alcalina 760 U/L 40 a 150 U/L Gama GT 900 U/L 9 a 36 U/L Bilirrubina total 6,2 mg/dL 0,2 mg/dL a 1,20 mg/dL Bilirrubina direta 5,1 mg/dL 0,1 a 0,4 mg/dL Amilase 80 U/L 28 a 100 U/L Nesse momento, quais são, respectivamente, o diagnóstico sindrômico e o exame complementar mais indicados para prosseguir à investigação?","sem_tabela_md5":"955ec0f5aff51a5502f42dd08824618e"}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('enamed-2025', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('enamed-2025', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('enamed-2025', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'ENAMED 2025: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 85)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'enamed-2025'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'enamed-2025' and situacao like 'pulado%'
) x order by ordem, resultado;
